"""Sparse reward variants of the MuJoCo locomotion tasks.

The paper uses the sparse reward versions of the MuJoCo games introduced by
Mazoure et al. (2019), where "the reward informs the x position of the agent
only if x > threshold" (Section C.2 of the paper):

    Hopper       x > 0.6
    Walker2d     x > 0.6
    HalfCheetah  x > 5
"""

from __future__ import annotations

from typing import Optional

import gymnasium as gym
import numpy as np


SPARSE_X_THRESHOLD = {
    "Hopper": 0.6,
    "Walker2d": 0.6,
    "HalfCheetah": 5.0,
}


class SparseLocomotionWrapper(gym.Wrapper):
    """Replace the dense locomotion reward by the sparse x-position reward."""

    def __init__(self, env: gym.Env, x_threshold: float):
        super().__init__(env)
        self.x_threshold = float(x_threshold)

    def _x_position(self) -> float:
        env = self.env.unwrapped
        try:
            return float(env.data.qpos[0])
        except AttributeError:  # pragma: no cover - defensive
            return float(env.state[0])

    def step(self, action):
        _, _, terminated, truncated, info = self.env.step(action)
        x = self._x_position()
        reward = x if x > self.x_threshold else 0.0
        info = dict(info)
        info["dense_reward"] = info.get("reward", None)
        info["x_position"] = x
        return self.env.unwrapped._get_obs(), float(reward), terminated, truncated, info


def make_sparse(env: gym.Env, base_name: str) -> gym.Env:
    """Wrap ``env`` so that it returns the sparse reward of ``base_name``."""
    if base_name not in SPARSE_X_THRESHOLD:
        raise KeyError("no sparse reward definition for {}".format(base_name))
    return SparseLocomotionWrapper(env, SPARSE_X_THRESHOLD[base_name])


def is_healthy(env: gym.Env) -> Optional[bool]:
    """Best effort healthy flag for the locomotion tasks."""
    unwrapped = env.unwrapped
    if hasattr(unwrapped, "is_healthy"):
        try:
            return bool(unwrapped.is_healthy)
        except TypeError:
            return bool(unwrapped.is_healthy())
    return None

"""State save/restore adapters.

RICE (Algorithm 2) and the fidelity metric (Experiment I) both need to put the
environment back into an *arbitrary previously visited state*: the refining
procedure resets the agent to a critical state, and the fidelity metric
fast-forwards the agent to the beginning of the most critical window.  The
paper follows (Ecoffet et al., 2019) and restores the simulator state directly;
this module implements that mechanism for every simulator used in the paper.

Every adapter exposes

    get_state()            -> hashable/copyable snapshot
    set_state(snapshot)    -> restore
    random_action()        -> uniform sample from the action space
    reset()/step()         -> thin passthrough to the wrapped env
"""

from __future__ import annotations

import copy
from typing import Any, Dict, Optional, Tuple

import numpy as np


class StatefulEnv:
    """Generic wrapper adding state snapshotting on top of a gymnasium env."""

    #: whether :meth:`set_state` is implemented for this environment
    supports_state_restore = True

    def __init__(self, env, name: str = "env"):
        self.env = env
        self.name = name

    # ------------------------------------------------------------------ gym
    @property
    def observation_space(self):
        return self.env.observation_space

    @property
    def action_space(self):
        return self.env.action_space

    @property
    def unwrapped(self):
        return self.env.unwrapped

    def reset(self, **kwargs) -> Tuple[np.ndarray, Dict[str, Any]]:
        out = self.env.reset(**kwargs)
        if isinstance(out, tuple):
            return out
        return out, {}

    def step(self, action):
        out = self.env.step(action)
        if len(out) == 5:
            return out
        obs, rew, done, info = out
        return obs, rew, done, False, info

    def close(self):
        self.env.close()

    def random_action(self):
        return self.action_space.sample()

    # ------------------------------------------------------------ snapshots
    def get_state(self) -> Dict[str, Any]:
        raise NotImplementedError(
            "{} does not implement state snapshots".format(type(self).__name__)
        )

    def set_state(self, state: Dict[str, Any]) -> None:
        raise NotImplementedError(
            "{} does not implement state snapshots".format(type(self).__name__)
        )


class MujocoStatefulEnv(StatefulEnv):
    """Snapshot/restore for MuJoCo environments (gymnasium ``* -v4`` ids).

    The full simulator state (``qpos``/``qvel``/``act`` plus the episode timer)
    is copied, which makes the environment behave exactly as it did when the
    snapshot was taken.  Environment specific extras (e.g. the random
    ``goal`` of ``Reacher``) are copied as well.
    """

    _EXTRA_ATTRS = ("goal", "target", "target_pos")

    def get_state(self) -> Dict[str, Any]:
        env = self.unwrapped
        data = env.data
        state: Dict[str, Any] = {
            "qpos": np.array(data.qpos, dtype=np.float64, copy=True),
            "qvel": np.array(data.qvel, dtype=np.float64, copy=True),
            "time": float(data.time),
        }
        act = getattr(data, "act", None)
        if act is not None and np.size(act) > 0:
            state["act"] = np.array(act, dtype=np.float64, copy=True)
        qacc_warmstart = getattr(data, "qacc_warmstart", None)
        if qacc_warmstart is not None and np.size(qacc_warmstart) > 0:
            state["qacc_warmstart"] = np.array(
                qacc_warmstart, dtype=np.float64, copy=True
            )
        mo = getattr(data, "mocap_pos", None)
        if mo is not None and np.size(mo) > 0:
            state["mocap_pos"] = np.array(mo, dtype=np.float64, copy=True)
            state["mocap_quat"] = np.array(
                data.mocap_quat, dtype=np.float64, copy=True
            )
        for attr in self._EXTRA_ATTRS:
            value = getattr(env, attr, None)
            if isinstance(value, np.ndarray):
                state[attr] = np.array(value, copy=True)
        steps = getattr(env, "_elapsed_steps", None)
        if steps is not None:
            state["steps"] = int(np.asarray(steps).reshape(-1)[0])
        return state

    def set_state(self, state: Dict[str, Any]) -> None:
        env = self.unwrapped
        env.set_state(np.array(state["qpos"]), np.array(state["qvel"]))
        data = env.data
        if "act" in state:
            data.act[:] = state["act"]
        data.time = state.get("time", 0.0)
        if "qacc_warmstart" in state:
            data.qacc_warmstart[:] = state["qacc_warmstart"]
        if "mocap_pos" in state:
            data.mocap_pos[:] = state["mocap_pos"]
            data.mocap_quat[:] = state["mocap_quat"]
        for attr in self._EXTRA_ATTRS:
            if attr in state:
                setattr(env, attr, np.array(state[attr], copy=True))
        if "steps" in state:
            env._elapsed_steps = state["steps"]
        if hasattr(env, "mujoco"):
            env.mujoco.mj_forward(env.model, env.data)


class CartPoleStatefulEnv(StatefulEnv):
    """Snapshot/restore for ``CartPole`` (used by the unit tests)."""

    def get_state(self) -> Dict[str, Any]:
        env = self.unwrapped
        return {
            "state": np.array(env.state, dtype=np.float64, copy=True),
            "steps": int(getattr(env, "_elapsed_steps", 0)),
        }

    def set_state(self, state: Dict[str, Any]) -> None:
        env = self.unwrapped
        env.state = np.array(state["state"], dtype=np.float64, copy=True)
        env._elapsed_steps = state.get("steps", 0)
        if hasattr(env, "steps_beyond_done"):
            env.steps_beyond_done = None


class DictStatefulEnv(StatefulEnv):
    """Generic deep-copy adapter.

    Works for pure-python environments that keep their whole state in
    ``env.unwrapped.__dict__`` (e.g. the selfish mining environment shipped in
    this repository).  Simulator backed environments whose state lives outside
    of python (CAGE / MetaDrive) need a dedicated adapter.
    """

    _SKIP = {"spec", "np_random", "_np_random"}

    def get_state(self) -> Dict[str, Any]:
        env = self.unwrapped
        state = {
            key: copy.deepcopy(value)
            for key, value in vars(env).items()
            if key not in self._SKIP
        }
        rng = getattr(env, "np_random", None)
        if rng is not None:
            state["__np_random__"] = copy.deepcopy(rng.bit_generator.state)
        return state

    def set_state(self, state: Dict[str, Any]) -> None:
        env = self.unwrapped
        rng_state = state.get("__np_random__")
        for key, value in state.items():
            if key == "__np_random__":
                continue
            setattr(env, key, copy.deepcopy(value))
        if rng_state is not None and getattr(env, "np_random", None) is not None:
            env.np_random.bit_generator.state = copy.deepcopy(rng_state)


class ActionReplayStatefulEnv(DictStatefulEnv):
    """Fallback for environments without a direct state setter.

    The state is represented by the *sequence of actions* that was executed
    since the last ``reset``.  Restoring replays that sequence deterministically.
    Only works when the environment is deterministic, and is used for the
    third-party simulators (CAGE Challenge 2, MetaDrive) where MuJoCo-style
    snapshotting is unavailable.
    """

    supports_state_restore = True

    def __init__(self, env, name: str = "env", seed: Optional[int] = None):
        super().__init__(env, name=name)
        self._seed = seed
        self._action_log: list = []
        self._last_obs = None

    def reset(self, **kwargs):
        obs, info = super().reset(**kwargs)
        self._action_log = []
        self._last_obs = obs
        return obs, info

    def step(self, action):
        out = super().step(action)
        self._action_log.append(copy.deepcopy(action))
        self._last_obs = out[0]
        return out

    def get_state(self) -> Dict[str, Any]:
        return {"actions": copy.deepcopy(self._action_log)}

    def set_state(self, state: Dict[str, Any]) -> None:
        actions = state["actions"]
        obs, _ = self.env.reset(seed=self._seed)
        for action in actions:
            obs, *_ = self.env.step(action)
        self._action_log = copy.deepcopy(actions)
        self._last_obs = obs

"""CAGE Challenge 2 wrapper (network defence application).

The paper evaluates a PPO blue agent defending a network against the red agent
"B-line" and reports the final reward as the sum of the average rewards of
episodes of length 30, 50 and 100 (Section C.2).

The simulator (``CybORG`` / ``cage-challenge-2``) is a heavy third party
dependency, therefore it is imported lazily.  Install it with::

    pip install CybORG

and place the champion agent configuration in ``RICE_CAGE_PATH`` (see the
README).  All the RICE machinery (mask network, critical state identification,
mixed initial state distribution, RND exploration) is simulator agnostic; this
module only provides the environment plumbing.
"""

from __future__ import annotations

import os
from typing import Any, Dict, Optional, Tuple

import numpy as np

from rice.envs.adapters import StatefulEnv

try:  # pragma: no cover - optional dependency
    from CybORG import CybORG  # type: ignore

    CYBORG_AVAILABLE = True
except Exception:  # pragma: no cover - optional dependency
    CybORG = None  # type: ignore
    CYBORG_AVAILABLE = False


EPISODE_LENGTHS = (30, 50, 100)


class CageChallengeEnv(StatefulEnv):
    """Thin wrapper exposing the CAGE-2 blue agent task as a stateful env."""

    supports_state_restore = True

    def __init__(
        self,
        episode_length: int = 30,
        scenario_path: Optional[str] = None,
        name: str = "cage",
    ):
        if not CYBORG_AVAILABLE:  # pragma: no cover - optional dependency
            raise ImportError(
                "CybORG is not installed. Run `pip install CybORG` to enable the "
                "CAGE Challenge 2 experiments."
            )
        scenario_path = scenario_path or os.environ.get("RICE_CAGE_PATH")
        if scenario_path is None:
            raise ValueError(
                "Set RICE_CAGE_PATH to the cage-challenge-2 YAML scenario file."
            )
        self.episode_length = int(episode_length)
        self.scenario_path = scenario_path
        self._cyborg = CybORG(scenario_path, "sim", seed=0, max_episode_length=episode_length)
        self._action_space = list(self._cyborg.action_space("Blue"))
        self._action_log: list = []
        super().__init__(env=None, name=name)

    # ------------------------------------------------------------- gym API
    @property
    def observation_space(self):
        obs = self._cyborg.get_observation("Blue")
        return _flatten_observation(obs)

    @property
    def action_space(self):
        return _DiscreteMask(len(self._action_space))

    @property
    def unwrapped(self):
        return self

    def random_action(self):
        return int(np.random.randint(len(self._action_space)))

    def reset(self, **kwargs) -> Tuple[np.ndarray, Dict[str, Any]]:
        self._cyborg.reset()
        self._action_log = []
        return self._obs(), {}

    def step(self, action):
        action = int(action)
        self._action_log.append(action)
        raw_action = self._action_space[action][1]
        obs = self._cyborg.step("Blue", raw_action).observation
        reward = float(obs.get("Blue", {}).get("reward", 0.0)) if isinstance(obs, dict) else 0.0
        truncated = len(self._action_log) >= self.episode_length
        return self._obs(), reward, False, truncated, {}

    def _obs(self) -> np.ndarray:
        return _flatten_observation(self._cyborg.get_observation("Blue"))

    def get_state(self) -> Dict[str, Any]:
        # CAGE-2 exposes the full simulator state through the low level API
        return {"actions": list(self._action_log)}

    def set_state(self, state: Dict[str, Any]) -> None:
        actions = state["actions"]
        self._cyborg.reset()
        self._action_log = []
        for action in actions:
            self.step(action)


def _flatten_observation(obs) -> np.ndarray:
    """Flatten the nested CAGE observation dictionary into a vector."""
    values: list = []

    def _walk(obj):
        if isinstance(obj, dict):
            for key in sorted(obj):
                _walk(obj[key])
        elif isinstance(obj, (list, tuple, np.ndarray)):
            for item in obj:
                _walk(item)
        elif isinstance(obj, (int, float, bool, np.integer, np.floating)):
            values.append(float(obj))

    _walk(obs)
    return np.asarray(values, dtype=np.float32)


class _DiscreteMask:
    """Minimal stand-in for ``spaces.Discrete`` (avoids a gym dependency)."""

    def __init__(self, n: int):
        self.n = n

    def sample(self):
        return int(np.random.randint(self.n))

    def contains(self, x) -> bool:
        return isinstance(x, (int, np.integer)) and 0 <= int(x) < self.n

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return "Discrete({})".format(self.n)

"""Neural networks used by RICE.

* :class:`ActorCritic` -- the policy/value network of the target agent and of
  the refining phase (PPO).  The paper relies on the default ``MlpPolicy`` of
  Stable-Baselines3 (two hidden layers of 64 units with ``tanh`` activations)
  for the MuJoCo tasks, on a 4x128 MLP for selfish mining and on a 3x64 MLP for
  the CAGE challenge.
* :class:`MaskNet` -- the *mask network* of Algorithm 1, a small MLP with a
  binary action head (blind / do not blind the target agent).
"""

from __future__ import annotations

from typing import Callable, Iterable, Optional, Sequence, Tuple

import numpy as np
import torch
import torch.nn as nn
from torch.distributions import Categorical, Normal


def _activation(name: str) -> nn.Module:
    name = name.lower()
    if name == "tanh":
        return nn.Tanh()
    if name == "relu":
        return nn.ReLU()
    if name == "gelu":
        return nn.GELU()
    raise ValueError("unknown activation {!r}".format(name))


def mlp(
    sizes: Sequence[int],
    activation: str = "tanh",
    output_activation: Optional[Callable[[], nn.Module]] = None,
) -> nn.Sequential:
    layers: list = []
    for i in range(len(sizes) - 1):
        layers.append(nn.Linear(sizes[i], sizes[i + 1]))
        if i < len(sizes) - 2:
            layers.append(_activation(activation))
    if output_activation is not None:
        layers.append(output_activation())
    return nn.Sequential(*layers)


def init_orthogonal(module: nn.Module, gain: float = np.sqrt(2)) -> None:
    for layer in module.modules():
        if isinstance(layer, nn.Linear):
            nn.init.orthogonal_(layer.weight, gain)
            nn.init.constant_(layer.bias, 0.0)


class ActorCritic(nn.Module):
    """Shared-trunk actor critic with a Gaussian (Box) or Categorical head."""

    def __init__(
        self,
        obs_dim: int,
        act_dim: int,
        hidden: Iterable[int] = (64, 64),
        discrete: bool = True,
        activation: str = "tanh",
        log_std_init: float = -0.5,
    ):
        super().__init__()
        self.obs_dim = int(obs_dim)
        self.act_dim = int(act_dim)
        self.discrete = bool(discrete)
        hidden = tuple(int(h) for h in hidden)

        self.shared = mlp((obs_dim,) + hidden, activation)
        self.pi = mlp((hidden[-1], act_dim), activation)
        init_orthogonal(self.pi, gain=0.01)
        self.vf = mlp((hidden[-1], 1), activation)
        init_orthogonal(self.vf, gain=1.0)
        if not self.discrete:
            self.log_std = nn.Parameter(
                torch.full((act_dim,), float(log_std_init), dtype=torch.float32)
            )

    # -------------------------------------------------------------- helpers
    def features(self, obs: torch.Tensor) -> torch.Tensor:
        return self.shared(obs)

    def value(self, obs: torch.Tensor) -> torch.Tensor:
        return self.vf(self.features(obs)).squeeze(-1)

    def dist(self, obs: torch.Tensor):
        h = self.features(obs)
        pi = self.pi(h)
        if self.discrete:
            return Categorical(logits=pi)
        mean = pi
        std = torch.exp(self.log_std).expand_as(mean)
        return Normal(mean, std)

    def forward(self, obs: torch.Tensor):
        return self.dist(obs), self.value(obs)

    # ------------------------------------------------------------ inference
    @torch.no_grad()
    def act(
        self, obs: np.ndarray, deterministic: bool = False
    ) -> Tuple[np.ndarray, float, float]:
        obs_t = torch.as_tensor(np.asarray(obs, dtype=np.float32))
        if obs_t.dim() == 1:
            obs_t = obs_t.unsqueeze(0)
        dist, value = self.forward(obs_t)
        if deterministic:
            if self.discrete:
                action = torch.argmax(dist.probs, dim=-1)
            else:
                action = dist.mean
        else:
            action = dist.sample()
        log_prob = dist.log_prob(action)
        if self.discrete:
            action_np = action.squeeze(-1).cpu().numpy().astype(np.int64)
        else:
            action_np = action.squeeze(0).cpu().numpy().astype(np.float32)
        return action_np, float(log_prob.sum().item()), float(value.squeeze(-1).item())

    def evaluate_actions(self, obs: torch.Tensor, actions: torch.Tensor):
        dist, value = self.forward(obs)
        log_prob = dist.log_prob(actions)
        if self.discrete:
            log_prob = log_prob.reshape(-1)
        else:
            log_prob = log_prob.sum(-1)
        entropy = dist.entropy()
        if not self.discrete:
            entropy = entropy.sum(-1)
        return log_prob, entropy, value

    @staticmethod
    def from_checkpoint(path: str, map_location: str = "cpu") -> "ActorCritic":
        ckpt = torch.load(path, map_location=map_location)
        model = ActorCritic(
            ckpt["obs_dim"],
            ckpt["act_dim"],
            hidden=ckpt.get("hidden", (64, 64)),
            discrete=ckpt.get("discrete", True),
            activation=ckpt.get("activation", "tanh"),
        )
        model.load_state_dict(ckpt["state_dict"])
        model.eval()
        return model

    def save(self, path: str) -> None:
        torch.save(
            {
                "state_dict": self.state_dict(),
                "obs_dim": self.obs_dim,
                "act_dim": self.act_dim,
                "hidden": tuple(
                    layer.out_features
                    for layer in self.shared
                    if isinstance(layer, nn.Linear)
                ),
                "discrete": self.discrete,
            },
            path,
        )


class MaskNet(nn.Module):
    """Binary mask network: ``a^m = 1`` blinds the target agent at this step."""

    MASK_KEEP = 0  # a^m = 0 -> the target agent uses its own action
    MASK_BLIND = 1  # a^m = 1 -> a uniformly random action is executed

    def __init__(
        self,
        obs_dim: int,
        hidden: Iterable[int] = (64, 64),
        activation: str = "tanh",
    ):
        super().__init__()
        self.obs_dim = int(obs_dim)
        hidden = tuple(int(h) for h in hidden)
        self.net = mlp((obs_dim,) + hidden + (2,), activation)
        init_orthogonal(self.net, gain=0.01)

    def forward(self, obs: torch.Tensor) -> torch.Tensor:
        return self.net(obs)

    def dist(self, obs: torch.Tensor) -> Categorical:
        return Categorical(logits=self.forward(obs))

    @torch.no_grad()
    def mask_prob(self, obs) -> np.ndarray:
        """Probability that the mask *blinds* the agent at ``obs``."""
        obs_t = torch.as_tensor(np.atleast_2d(np.asarray(obs, dtype=np.float32)))
        probs = self.dist(obs_t).probs[..., self.MASK_BLIND]
        return probs.cpu().numpy()

    @torch.no_grad()
    def importance(self, obs) -> np.ndarray:
        """Importance score of Algorithm 1: ``P(a^m = 0 | s)``."""
        obs_t = torch.as_tensor(np.atleast_2d(np.asarray(obs, dtype=np.float32)))
        probs = self.dist(obs_t).probs[..., self.MASK_KEEP]
        return probs.cpu().numpy()

    @staticmethod
    def from_checkpoint(path: str, map_location: str = "cpu") -> "MaskNet":
        ckpt = torch.load(path, map_location=map_location)
        model = MaskNet(ckpt["obs_dim"], hidden=ckpt.get("hidden", (64, 64)))
        model.load_state_dict(ckpt["state_dict"])
        model.eval()
        return model

    def save(self, path: str) -> None:
        torch.save(
            {
                "state_dict": self.state_dict(),
                "obs_dim": self.obs_dim,
                "hidden": tuple(
                    layer.out_features
                    for layer in self.net
                    if isinstance(layer, nn.Linear)
                )[:-1],
            },
            path,
        )

"""Turning mask probabilities into critical states / critical windows."""

from __future__ import annotations

from typing import Optional, Sequence, Tuple

import numpy as np


def importance_scores(mask_net, states: np.ndarray) -> np.ndarray:
    """Importance of every step: ``P(a^m = 0 | s_t)`` (higher = more critical)."""
    states = np.asarray(states, dtype=np.float32)
    if states.ndim == 1:
        states = states[None, :]
    return np.asarray(mask_net.importance(states), dtype=np.float64).reshape(-1)


def most_critical_state(scores: Sequence[float]) -> int:
    """Index of the single most critical step (Algorithm 2, roll-in step)."""
    scores = np.asarray(scores, dtype=np.float64)
    return int(np.argmax(scores))


def topk_critical_states(scores: Sequence[float], k: int) -> np.ndarray:
    scores = np.asarray(scores, dtype=np.float64)
    k = int(max(1, min(k, len(scores))))
    return np.argsort(-scores)[:k]


def most_critical_window(
    scores: Sequence[float], window: int, stride: int = 1
) -> Tuple[int, int]:
    """Sliding window of width ``window`` with the highest average importance.

    This is the selection rule of the fidelity score (Section 4.1 / StateMask).
    """
    scores = np.asarray(scores, dtype=np.float64)
    n = len(scores)
    window = int(max(1, min(window, n)))
    if window >= n:
        return 0, n
    csum = np.concatenate([[0.0], np.cumsum(scores)])
    starts = np.arange(0, n - window + 1, stride)
    averages = (csum[starts + window] - csum[starts]) / window
    best = int(starts[int(np.argmax(averages))])
    return best, best + window


def normalize_scores(scores: np.ndarray) -> np.ndarray:
    scores = np.asarray(scores, dtype=np.float64)
    lo, hi = float(scores.min()), float(scores.max())
    if hi - lo < 1e-12:
        return np.zeros_like(scores)
    return (scores - lo) / (hi - lo)

"""Running statistics (used by RND normalisation and observation normalisation)."""

from __future__ import annotations

import numpy as np


class RunningMeanStd:
    """Incremental mean/variance estimate (Welford / parallel algorithm)."""

    def __init__(self, shape=(), epsilon: float = 1e-4):
        self.mean = np.zeros(shape, dtype=np.float64)
        self.var = np.ones(shape, dtype=np.float64)
        self.count = float(epsilon)

    def update(self, x: np.ndarray) -> None:
        x = np.asarray(x, dtype=np.float64)
        if x.ndim == len(self.mean.shape):
            x = x[None, ...]
        batch_mean = x.mean(axis=0)
        batch_var = x.var(axis=0)
        batch_count = x.shape[0]
        self._update_from_moments(batch_mean, batch_var, batch_count)

    def _update_from_moments(self, batch_mean, batch_var, batch_count: float) -> None:
        delta = batch_mean - self.mean
        total = self.count + batch_count
        new_mean = self.mean + delta * batch_count / total
        m_a = self.var * self.count
        m_b = batch_var * batch_count
        m2 = m_a + m_b + np.square(delta) * self.count * batch_count / total
        self.mean = new_mean
        self.var = m2 / total
        self.count = total

    @property
    def std(self) -> np.ndarray:
        return np.sqrt(np.maximum(self.var, 1e-8))

    def normalize(self, x: np.ndarray, clip: float = 10.0) -> np.ndarray:
        x = np.asarray(x, dtype=np.float32)
        out = (x - self.mean) / self.std
        if clip is not None:
            out = np.clip(out, -clip, clip)
        return out.astype(np.float32)

    def state_dict(self) -> dict:
        return {"mean": self.mean, "var": self.var, "count": self.count}

    def load_state_dict(self, state) -> None:
        self.mean = np.asarray(state["mean"], dtype=np.float64)
        self.var = np.asarray(state["var"], dtype=np.float64)
        self.count = float(state["count"])

"""Fidelity score of an explanation method (Experiment I).

Pipeline (Section 4.1 and the addendum of the paper):

1. the explanation method produces a step level importance score for every
   step of a trajectory sampled from the pre-trained policy ``pi``;
2. a sliding window of width ``l = K * L`` selects the most critical segment
   (highest average importance);
3. the agent is fast-forwarded to the beginning of that segment and executes
   *random* actions for ``l`` steps, after which it continues with ``pi`` until
   the episode terminates;
4. with ``R`` the original episode reward and ``R'`` the perturbed one,
   ``d = |R' - R|`` and

        fidelity = log(d / d_max) - log(l / L)

A higher score means that randomising the identified steps indeed destroys the
episode reward, i.e. the explanation is faithful.
"""

from __future__ import annotations

import dataclasses
from typing import Callable, Dict, List, Optional, Sequence

import numpy as np

from rice.explanation.critical_states import most_critical_window
from rice.rollout import rollout_episode


@dataclasses.dataclass
class FidelityConfig:
    n_trajectories: int = 500
    k_values: Sequence[float] = (0.1, 0.2, 0.3, 0.4)
    #: largest reward the environment allows in one episode ("d_max")
    d_max: float = 1.0
    seed: int = 0
    max_steps: Optional[int] = None
    deterministic_policy: bool = False
    collect_snapshots: bool = True


def random_importance(states: np.ndarray, rng: np.random.RandomState) -> np.ndarray:
    """The "Random" baseline explanation: a random score per step."""
    n = len(states)
    return rng.rand(n)


def _action_sequence_fn(env, policy, random_steps: int, start_index: int = 0):
    counter = {"t": 0}

    def _fn(obs):
        if counter["t"] < random_steps:
            counter["t"] += 1
            return env.random_action()
        counter["t"] += 1
        return policy.act(obs, deterministic=policy_deterministic[0])

    return _fn


def fidelity_scores_for_trajectory(
    env,
    policy,
    importance_fn: Callable[[np.ndarray], np.ndarray],
    k_values: Sequence[float],
    d_max: float,
    deterministic_policy: bool = False,
    max_steps: Optional[int] = None,
) -> Dict[float, float]:
    """Compute the fidelity score of one trajectory for every ``K``."""
    global policy_deterministic
    policy_deterministic = [deterministic_policy]

    action_fn = lambda obs: policy.act(obs, deterministic=deterministic_policy)
    episode = rollout_episode(
        env, action_fn, max_steps=max_steps, record_snapshots=True
    )
    L = episode.length
    if L == 0:
        return {k: float("nan") for k in k_values}
    original_reward = episode.total_reward
    scores = np.asarray(importance_fn(episode.obs_array()), dtype=np.float64)

    results: Dict[float, float] = {}
    for k in k_values:
        l = int(round(k * L))
        if l < 1:
            results[k] = float("nan")
            continue
        start, end = most_critical_window(scores, l)
        counter = {"t": 0}

        def perturbed_fn(obs, _l=l):
            if counter["t"] < _l:
                counter["t"] += 1
                return env.random_action()
            counter["t"] += 1
            return policy.act(obs, deterministic=deterministic_policy)

        perturbed = rollout_episode(
            env,
            perturbed_fn,
            max_steps=max_steps,
            snapshot=episode.snapshots[start],
        )
        d = abs(perturbed.total_reward - original_reward)
        d = max(d, 1e-8)
        results[k] = float(
            np.log(d / abs(d_max)) - np.log(l / float(L))
        )
    return results


def compute_fidelity(
    env,
    policy,
    importance_fn: Callable[[np.ndarray], np.ndarray],
    config: Optional[FidelityConfig] = None,
    n_seeds: int = 3,
) -> Dict[str, object]:
    """Fidelity scores over ``n_trajectories`` trajectories and ``n_seeds`` runs.

    Returns a dictionary with the per-``K`` mean/std over the seeds, plus the
    raw per-seed values (used to draw the error bars of Figure 5).
    """
    config = config or FidelityConfig()
    per_seed: Dict[float, List[float]] = {
        float(k): [] for k in config.k_values
    }
    raw: List[Dict[float, float]] = []
    for seed_offset in range(n_seeds):
        rng = np.random.RandomState(config.seed + seed_offset)
        np.random.seed(config.seed + seed_offset)
        values: List[Dict[float, float]] = []
        for _ in range(config.n_trajectories):
            values.append(
                fidelity_scores_for_trajectory(
                    env,
                    policy,
                    lambda states, _rng=rng: importance_fn(states, _rng)
                    if importance_fn.__code__.co_argcount > 1
                    else importance_fn(states),
                    config.k_values,
                    config.d_max,
                    deterministic_policy=config.deterministic_policy,
                    max_steps=config.max_steps,
                )
            )
        raw.append(values)
        for k in config.k_values:
            finite = [v[float(k)] for v in values if np.isfinite(v[float(k)])]
            per_seed[float(k)].append(float(np.mean(finite)) if finite else float("nan"))

    summary = {
        "k": [float(k) for k in config.k_values],
        "mean": [
            float(np.nanmean(per_seed[float(k)])) for k in config.k_values
        ],
        "std": [
            float(np.nanstd(per_seed[float(k)])) for k in config.k_values
        ],
        "per_seed": {str(k): v for k, v in per_seed.items()},
        "d_max": config.d_max,
        "n_trajectories": config.n_trajectories,
        "n_seeds": n_seeds,
    }
    return summary


def mask_importance_fn(mask_net):
    """Importance function of the mask network (``P(a^m = 0 | s)``)."""

    def _fn(states: np.ndarray) -> np.ndarray:
        return np.asarray(mask_net.importance(states), dtype=np.float64).reshape(-1)

    return _fn


def random_importance_fn(seed: int = 0):
    rng = np.random.RandomState(seed)

    def _fn(states: np.ndarray) -> np.ndarray:
        return random_importance(states, rng)

    return _fn

"""Shared helpers for the experiment drivers (checkpoints, JSON I/O)."""

from __future__ import annotations

import dataclasses
import json
import os
from typing import Any, Dict, List, Optional

import numpy as np
import torch

from rice.envs.registry import ENV_SPECS, make_env
from rice.networks import ActorCritic
from rice.policies import TorchPolicy
from rice.training import evaluate_policy


DEFAULT_ROOT = os.environ.get("RICE_ROOT", ".")


def ckpt_path(name: str, kind: str = "agents", root: Optional[str] = None) -> str:
    root = root or DEFAULT_ROOT
    folder = {"agents": "checkpoints/agents", "masks": "checkpoints/masks", "results": "results"}[kind]
    return os.path.join(root, folder, name)


def ensure_dir(path: str) -> str:
    os.makedirs(path, exist_ok=True)
    return path


def save_json(obj: Any, path: str) -> None:
    ensure_dir(os.path.dirname(os.path.abspath(path)))
    with open(path, "w") as handle:
        json.dump(obj, handle, indent=2, default=_json_default)


def load_json(path: str) -> Any:
    with open(path, "r") as handle:
        return json.load(handle)


def _json_default(obj):
    if isinstance(obj, (np.floating,)):
        return float(obj)
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    if isinstance(obj, torch.Tensor):
        return obj.detach().cpu().numpy().tolist()
    return str(obj)


def load_agent(env_name: str, path: str, device: str = "cpu") -> ActorCritic:
    """Load a pre-trained target agent (``checkpoints/agents/<env>.pt``)."""
    ckpt = torch.load(path, map_location=device)
    spec = ENV_SPECS[env_name]
    if "state_dict" in ckpt:
        policy = ActorCritic(
            ckpt["obs_dim"],
            ckpt["act_dim"],
            hidden=ckpt.get("hidden", spec.policy_hidden),
            discrete=ckpt.get("discrete", True),
        )
        policy.load_state_dict(ckpt["state_dict"])
    else:
        raise ValueError("unexpected checkpoint format in {}".format(path))
    policy.eval()
    return policy


def clone_policy(policy: ActorCritic) -> ActorCritic:
    import copy

    with torch.no_grad():
        clone = copy.deepcopy(policy)
    return clone


def evaluate_agent(env_name: str, policy, n_episodes: int = 10, seed: int = 1234) -> Dict[str, float]:
    env = make_env(env_name, seed=seed)
    try:
        return evaluate_policy(env, TorchPolicy(policy), n_episodes=n_episodes)
    finally:
        close_env(env)


def close_env(env) -> None:
    try:
        env.close()
    except Exception:  # pragma: no cover - optional simulators
        pass


def mean_std(values: List[float]) -> Dict[str, float]:
    values = [v for v in values if np.isfinite(v)]
    if not values:
        return {"mean": float("nan"), "std": float("nan")}
    return {"mean": float(np.mean(values)), "std": float(np.std(values))}

