from rice.explanation.mask_trainer import MaskTrainingConfig, train_mask_network
from rice.ppo_core import PPOConfig
H=8; C=4
class E(gym.Env):
    def __init__(self):
        self.observation_space=spaces.Box(0,1,(H,),np.float32); self.action_space=spaces.Discrete(2)
        self.t=0; self.ok=False
    def reset(self, seed=None, options=None):
        self.t=0; self.ok=False; return self._obs(), {}
    def _obs(self):
        o=np.zeros(H,np.float32); o[min(self.t,H-1)]=1.0; return o
    def step(self,a):
        a=int(a)
        if self.t==C and a==1: self.ok=True
        self.t+=1; done=self.t>=H
        return self._obs(), (1.0 if done and self.ok else 0.0), done, False, {}
class P:
    def act(self,obs,deterministic=False): return 1 if int(np.argmax(obs))==C else 0

def run(alpha, iters, roll, norm_adv=True, lr=3e-3, ne=4, seed=0):
    torch.manual_seed(seed); np.random.seed(seed)
    env=DictStatefulEnv(E())
    cfg=MaskTrainingConfig(iterations=iters, rollout_length=roll, alpha=alpha, seed=seed, log_interval=10000,
                           ppo=PPOConfig(learning_rate=lr, n_epochs=ne, batch_size=32, normalize_advantage=norm_adv))
    res=train_mask_network(env, P(), cfg, verbose=False)
    probs=[float(res.mask_net.mask_prob(np.eye(H,dtype=np.float32)[t:t+1])[0]) for t in range(H)]
    imp=[1-p for p in probs]
    return np.round(probs,3), int(np.argmax(imp))

for alpha, iters, roll, na in [(0.05,400,8,True),(0.05,400,80,True),(0.05,400,80,False),(0.01,400,80,True),(0.001,400,80,True),(0.05,100,400,True)]:
    p,am = run(alpha,iters,roll,na)
    print("alpha=%.3f iters=%d roll=%d norm=%s -> P(mask=1)=%s argmax_imp=%d" % (alpha,iters,roll,na,p,am))
