```python
@property
def observation_space(self):
    if getattr(self, "_obs_dim", None) is None:
        obs, _ = self.reset()
        self._obs_dim = int(np.prod(np.asarray(obs).shape))
    return spaces.Box(low=-np.inf, high=np.inf, shape=(self._obs_dim,), dtype=np.float32)
```
